  qr: {
    /** Şube QR'ının kodu: hiç değişmez, başka şubeye verilmez */
    code: string;
    /** QR'ın taşıdığı adres: `https://rewloy.com/s/{code}` */
    url: string;
    /** `live` müşteri kart alabilir · `empty` QR'da şu an alınabilecek kart yok (basmadan önce bakın) · `frozen` şube geçici olarak kapalı · `archived` şube kapandı */
    state: 'live' | 'empty' | 'frozen' | 'archived';
  };
  /** 1.3.0: şubenin sürmekte olan ya da planlı dondurması (BRANCH-QR §6); yoksa null. `archived` değişmedi. */
  frozen: {
    /** Dondurmanın ilk günü (bugünden sonraysa planlı) */
    startsOn: string;
    /** O gün 00:00'da kendiliğinden açılır; null = belli değil */
    reopensOn: string | null;
    reason: 'renovation' | 'seasonal' | 'temporary' | 'other';
    /** Şubenin QR sayfasında müşterilere görünen not */
    publicNote: string | null;
  } | null;
