/** Every operationId. */
export type OperationId = keyof Operations;

/** The paged lists: `Rewloy.paginate` walks them. */
export type PagedOperationId =
  | 'listPassOperations'
  | 'listCustomers'
  | 'listCustomerCards'
  | 'customerTimeline'
  | 'listBlockedEmails'
  | 'listBlockedPhones'
  | 'listAllBatches'
  | 'listBatchCards'
  | 'listSeenLines'
  | 'listEarnRuleRevisions'
  | 'listSegmentCards'
  | 'listCampaigns'
  | 'listCampaignRecipients'
  | 'listAutomationRecipients'
  | 'listSequenceRecipients'
  | 'listActivity'
  | 'listAccessLog'
  | 'listShopOrders'
  | 'holderNotifications'
  | 'listShopRedemptions'
  | 'listApiKeyRequests'
  | 'listWebhookDeliveries'
  | 'listTestMessages'
  | 'listNotifications'
  | 'listTickets';

